from pathlib import Path
import json,hashlib,html
root=Path(__file__).resolve().parents[2];out=root/'output/validation/embedding-advanced'
data=json.loads((out/'dataset.json').read_text());sha=hashlib.sha256((out/'dataset.json').read_bytes()).hexdigest()
assert sha==(out/'dataset.sha256').read_text().strip()
names={'qwen':'Qwen3 Q8','e5':'E5-small','bge':'BGE-M3 dense','gemma':'EmbeddingGemma'}
results=[json.loads((out/f'{m}.json').read_text()) for m in names]
assert all(r['dataset_sha256']==sha for r in results)
life=json.loads((out/'lifecycle.json').read_text());assert life['dataset_sha256']==sha
rows=[];failures=[]
for r in results:
 basic=json.loads((root/f"output/validation/embedding-comparison/{r['model']}.json").read_text())
 n=sum(q['all_at4'] for q in r['results']);n8=sum(all(rank<=8 for rank in q['gold_ranks']) for q in r['results'])
 rows.append(f"<tr><th>{names[r['model']]}</th><td>{round(basic['all_at4']*40)}/40</td><td>{n}/40</td><td>{n8}/40</td><td>{r['index_seconds']:.1f}초</td><td>{r['query_p50_ms']:.1f}ms</td><td>{r['peak_process_rss_mib']:.0f}MiB</td><td>{r['max_input_tokens']}</td></tr>")
 for q in r['results']:
  if q['all_at4']:continue
  texts={p['id']:p['text'] for p in data['passages']}
  failures.append(f"<details><summary>{names[r['model']]} · {html.escape(q['query'])} · 근거 순위 {q['gold_ranks']}</summary><h4>필요한 원문</h4>"+''.join('<blockquote>'+html.escape(t)+'</blockquote>' for t in q['gold_texts'])+'<h4>실제 상위 4개 청크</h4>'+''.join('<p>'+html.escape(texts[g])+'</p>' for g in q['top4'])+'</details>')
labels={'growth_10':'10회차 초기 인덱싱','growth_30':'30회차까지 추가분만 인덱싱','growth_50':'50회차까지 추가분만 인덱싱','unchanged_sync':'변경 없는 원고 재임베딩 없음','reopen_no_reembedding':'저장소 다시 열기 후 기존 인덱스 재사용','revision_index':'수정 전 원문 제거 및 수정 원문 저장','revision_only_changed_document':'수정한 문서만 재임베딩','revision_retrieval':'수정된 계약 거절 근거 검색','deletion':'삭제한 문서가 인덱스와 검색에서 사라짐','deletion_no_reembedding':'삭제 시 나머지 원고 재임베딩 없음','chapter_filter':'지정한 회차 범위만 검색','project_isolation':'다른 작품의 원문 차단','addition':'새 회차 자동 인덱싱 및 검색'}
checks=''.join(f"<li>{'통과' if c['passed'] else '실패'} · {labels.get(c['name'],c['name'])}"+(f" · 재임베딩 {c['embedded_chunks']}개" if 'embedded_chunks' in c else '')+'</li>' for c in life['checks'])
text=f'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Story Guard 심화 검색 검사</title><style>body{{font:16px/1.7 system-ui;background:#F7F5EF;color:#252A27;margin:0}}main{{max-width:1200px;margin:auto;padding:40px 24px}}section,details{{background:#FFFDF8;border:1px solid #DADFD8;padding:20px;margin:16px 0;border-radius:8px}}table{{border-collapse:collapse;white-space:nowrap;width:100%}}td,th{{padding:12px;border-bottom:1px solid #DADFD8;text-align:left}}th,a{{color:#24635B}}.table{{overflow:auto}}summary{{cursor:pointer}}blockquote{{background:#E6EFEB;padding:12px}}code{{overflow-wrap:anywhere}}</style><main><a href="../embedding-comparison/index.html">← 기초 검사</a><h1>원고가 길어지면 근거 검색은 유지되는가?</h1><p><a href="../retrieval-strategies/index.html">검색 방식 개선 비교와 앱 적용 결과 →</a></p><p>50회차 · {sum(len(c['text']) for c in data['chapters']):,}자 · {len(data['passages'])}청크 · 40질문 · GPT 호출 0회</p><section><h2>네 모델의 분량·방해 문맥 스트레스 검사</h2><p>실제 RagService의 900자·120자 중복 청킹을 사용했다. 모델별 공식 입력 형식을 유지하고 CPU 4스레드에서 순차 측정했다. Top4/Top8은 필요한 원문을 모두 포함한 문항 수다. 중복 청크 중 하나만 검색돼도 해당 근거를 인정한다.</p><div class="table"><table><tr><th>모델</th><th>기초 Top4</th><th>심화 Top4</th><th>심화 Top8</th><th>전체 임베딩</th><th>검색 중앙값</th><th>최대 RSS</th><th>최대 입력 토큰</th></tr>{''.join(rows)}</table></div></section><section><h2>실제 앱 저장·검색 경로 검사: {life['passed']}/{life['total']} 통과</h2><p>SQLite 저장소, Chroma 인덱스, 실제 Qwen 임베딩을 사용했다. 10→30→50회차 누적, 재동기화, 저장소 다시 열기, 수정·삭제·추가, 회차 필터, 작품 격리를 확인했다. 별도 DB로 실행했으며 사용자 작품은 변경하지 않았다. 이 부분은 앱의 기본 GPU 설정으로 실행하여 위 CPU 시간과 비교하지 않는다.</p><ul>{checks}</ul></section><section><h2>이 결과의 범위</h2><ul><li>기초 검사의 40개 질문·설정 사실을 재사용해 긴 문맥 안에 배치했다. 독립 평가 원고에서의 일반화 정확도는 아니다.</li><li>12만 자는 서로 연결된 작가의 완성 소설이 아니라 고정 난수로 조합한 반복 템플릿이다. 비슷한 인물·아이템 이름과 확인되지 않은 소문이 방해 문맥에 들어간다.</li><li>비교 검색은 사람이 작성한 질문을 사용한 정규화 벡터의 정확한 코사인 순위다. 실제 GPT 분석 경로는 원고 청크 자체를 질의로 쓰므로 이 점수가 그대로 최종 분석 성능은 아니다. 실제 Chroma 검색·수정 반영은 별도 Qwen 앱 검사로만 확인했다. 다른 세 모델의 앱 통합은 검증하지 않았다.</li><li>Qwen은 Q8/llama.cpp, 나머지는 FP32/PyTorch다. 단일 실행이므로 GPU·Windows 성능이나 모델 자체의 절대 우열을 주장하지 않는다.</li><li>Top8은 같은 순위에서 검색 폭을 넓혔을 때의 참고치다. GPT 입력량과 오탐 변화는 측정하지 않았다.</li><li>입력은 토큰 한도를 넘어 자르지 않았다. 최종 충돌 판단·떡밥 회수 판단은 아직 GPT 검증이 필요하다.</li></ul><p>다음 판단: 검색 누락 사례를 기준으로 청킹 크기·주변 근거 확장·키워드 검색 결합을 비교한 뒤, 별도 원고로 다시 평가한다. 이번 결과만으로 앱 기본 모델이나 검색 설정을 변경하지 않는다.</p><code>데이터 SHA256: {sha}</code></section><h2>모든 실패 문항과 실제 검색 원문</h2>{''.join(failures)}</main></html>'''
(out/'index.html').write_text(text)
(root/'docs/embedding-advanced-validation.md').write_text('# 심화 검색 검사\n\n보고서: `output/validation/embedding-advanced/index.html`\n\n'+ '\n'.join(f"- {names[r['model']]}: Top4 {sum(q['all_at4'] for q in r['results'])}/40, Top8 {sum(all(k<=8 for k in q['gold_ranks']) for q in r['results'])}/40, {r['index_seconds']:.1f}초 인덱싱" for r in results)+f"\n\n앱 경로 검사 {life['passed']}/{life['total']}. 합성 스트레스 시험이며 실제 장편 소설 및 GPT 판단 정확도는 미검증. 모델별 전체 측정값/실패 원문/검사 결과는 JSON과 HTML에 보존.\n\n재현: build_advanced 모듈로 데이터 생성, run 모듈에 --dataset 및 --output으로 위 출력 디렉터리 지정, lifecycle 모듈 실행 후 report_advanced 모듈 실행. CPU 네 모델은 순차 실행. lifecycle은 별도 DB와 기본 GPU 설정 사용.\n")
print('Advanced reports generated and dataset identity verified.')
